// Des: Probe: dump the page's AX tree with personal text hashed, replay dumps as fixtures
// Flo: node + registry > keep exact labels, hash everything else > json dump > fixture parse back to nodes
// I/O: nodes + page text + Reg (caller) > redacted json text; fixture json > nodes
// ===================================================================
const std = @import("std"); const snap = @import("ru-page-snap.zig"); const lab = @import("cf-labl-load.zig");
pub fn token(aren: std.mem.Allocator, text: []const u8) ![]const u8 { var dig: [32]u8 = undefined; std.crypto.hash.sha2.Sha256.hash(text, &dig, .{}); const hex = std.fmt.bytesToHex(dig[0..4].*, .lower); return std.fmt.allocPrint(aren, "«h:{s}:{d}»", .{ hex, text.len }); }
fn labelHit(reg: *const lab.Reg, name: []const u8) ?[]const u8 { var it = reg.keys.map.iterator(); while (it.next()) |ent| { for (ent.value_ptr.vi) |nam| { if (nam.len > 0 and std.ascii.eqlIgnoreCase(nam, name)) return nam; } for (ent.value_ptr.en) |nam| { if (nam.len > 0 and std.ascii.eqlIgnoreCase(nam, name)) return nam; } } return null; }
fn prefixHit(reg: *const lab.Reg, name: []const u8) ?[]const u8 { var it = reg.keys.map.iterator(); while (it.next()) |ent| { for (ent.value_ptr.vi) |nam| { if (nam.len > 0 and name.len > nam.len and std.mem.startsWith(u8, name, nam) and name[nam.len] == ' ') return nam; } for (ent.value_ptr.en) |nam| { if (nam.len > 0 and name.len > nam.len and std.mem.startsWith(u8, name, nam) and name[nam.len] == ' ') return nam; } } return null; }
pub fn redactName(aren: std.mem.Allocator, reg: *const lab.Reg, name: []const u8) ![]const u8 { if (name.len == 0) return name; if (labelHit(reg, name) != null) return name; if (prefixHit(reg, name)) |pre| return std.fmt.allocPrint(aren, "{s} {s}", .{ pre, try token(aren, name[pre.len + 1 ..]) }); return token(aren, name); }
const Rown = struct { r: []const u8, n: []const u8 };
const Dump = struct { ver: u32 = 1, ts: i64, nodes: []const Rown, text: []const []const u8 };
pub fn dump(aren: std.mem.Allocator, reg: *const lab.Reg, nodes: []const snap.Node, text: []const u8, ts: i64) ![]u8 { var rows: std.ArrayList(Rown) = .empty; for (nodes) |nod| { if (nod.name.len == 0 and nod.role.len == 0) continue; try rows.append(aren, .{ .r = nod.role, .n = try redactName(aren, reg, nod.name) }); } var toks: std.ArrayList([]const u8) = .empty; var itr = std.mem.splitScalar(u8, text, '\n'); while (itr.next()) |ln| { const trm = std.mem.trim(u8, ln, " \r\t"); if (trm.len > 0) try toks.append(aren, try redactName(aren, reg, trm)); } return std.json.Stringify.valueAlloc(aren, Dump{ .ts = ts, .nodes = rows.items, .text = toks.items }, .{}); }
pub fn fromFixture(aren: std.mem.Allocator, text: []const u8) ![]snap.Node { const val = std.json.parseFromSliceLeaky(std.json.Value, aren, text, .{}) catch return error.BadConfig; if (val != .object) return error.BadConfig; const arr = val.object.get("nodes") orelse return error.BadConfig; if (arr != .array) return error.BadConfig; var out: std.ArrayList(snap.Node) = .empty; for (arr.array.items, 0..) |itm, idx| { if (itm != .object) continue; const rv = itm.object.get("r") orelse continue; const nv = itm.object.get("n") orelse continue; if (rv != .string or nv != .string) continue; try out.append(aren, .{ .role = rv.string, .name = nv.string, .valu = "", .bid = @intCast(idx + 1) }); } return out.items; }
